            if (i + 1) % 20 == 0:
                print(f"  Progress: {i + 1}/100 audits assessed...")

            # Quantum assessment
            q_assessment = quantum_assessor.assess_compliance(audit)
            quantum_times.append(q_assessment.evaluation_time_ms)
